   let entryAt: string | null = null; // the address of this module's entry while it is current, live or spent
   let staleBelow = false; // a replacing navigate moved off the entry below: Back skips it
   let skipNext = false; // the next popstate is this module's own step back off a spent entry
   let listening = false;
   const answered = new WeakMap<Event, boolean>();

